<script lang="ts">import { avatarImageClassName } from '@fex-design/styles/avatar';import { cn } from '@fex/utils';import { getContext } from 'svelte';import type { HTMLImgAttributes } from 'svelte/elements';import { avatarContextKey,type AvatarContext } from './context';interface Props extends Omit<HTMLImgAttributes,'class'>{class?:string}let{class:className,onload,onerror,...rest}:Props=$props();const{loaded}=getContext<AvatarContext>(avatarContextKey)</script>
<img {...rest} hidden={!$loaded} data-slot="avatar-image" class={cn(avatarImageClassName,className)} onload={(event)=>{loaded.set(true);onload?.(event)}} onerror={(event)=>{loaded.set(false);onerror?.(event)}}/>
